import { motion } from 'framer-motion';

const title = "RBT MISSION LEARNING".split("");
const tagline = "MISSION HAI TOH PERFECT LEARNING CHAHIYE".split(" ");

export default function LoadingScreen() {
  return (
    <div className="fixed inset-0 bg-black flex flex-col items-center justify-center z-[200] overflow-hidden">
      {/* Background Animated Gradient / Glow */}
      <motion.div 
        className="absolute w-[300px] h-[300px] md:w-[600px] md:h-[600px] bg-green-brand/20 rounded-full blur-[80px] md:blur-[120px]"
        animate={{
          scale: [1, 1.2, 1],
          opacity: [0.4, 0.7, 0.4],
        }}
        transition={{ duration: 4, repeat: Infinity, ease: "easeInOut" }}
      />
      
      {/* Floating Particles */}
      {[...Array(15)].map((_, i) => (
        <motion.div
          key={i}
          className="absolute w-1 h-1 bg-green-light rounded-full opacity-0"
          initial={{ 
            y: "110vh", 
            x: `${(Math.random() - 0.5) * 100}vw`,
            scale: Math.random() * 1.5 + 0.5
          }}
          animate={{ 
            y: "-10vh",
            opacity: [0, 0.9, 0]
          }}
          transition={{
            duration: 3 + Math.random() * 3,
            repeat: Infinity,
            delay: Math.random() * 2,
            ease: "linear"
          }}
        />
      ))}

      <div className="relative z-10 flex flex-col items-center w-full px-6 text-center">
        {/* Animated Logo */}
        <motion.div
          initial={{ scale: 0, rotate: -180, opacity: 0 }}
          animate={{ scale: 1, rotate: 0, opacity: 1 }}
          transition={{ type: "spring", stiffness: 200, damping: 20, duration: 1 }}
        >
          <motion.img
            src="/Images/RBT Logo.jpeg"
            alt="RBT Mission Learning"
            animate={{ 
              y: [-8, 8, -8],
              boxShadow: [
                "0px 0px 25px rgba(34,197,94,0.3)", 
                "0px 0px 50px rgba(34,197,94,0.6)", 
                "0px 0px 25px rgba(34,197,94,0.3)"
              ]
            }}
            transition={{ duration: 3, repeat: Infinity, ease: 'easeInOut' }}
            className="w-20 h-20 md:w-28 md:h-28 rounded-[1.5rem] md:rounded-[2rem] object-cover mb-6 md:mb-8 border border-white/20"
          />
        </motion.div>

        {/* Staggered Title */}
        <h2 className="text-white font-bold text-lg sm:text-2xl md:text-4xl tracking-[0.1em] sm:tracking-[0.15em] md:tracking-widest mb-4 font-[var(--font-heading)] drop-shadow-[0_4px_12px_rgba(0,0,0,0.8)] flex flex-wrap justify-center gap-[2px] sm:gap-1 md:gap-1.5">
          {title.map((letter, index) => (
            <motion.span
              key={index}
              initial={{ opacity: 0, y: 20, scale: 0.8 }}
              animate={{ opacity: 1, y: 0, scale: 1 }}
              transition={{ duration: 0.4, delay: 0.5 + index * 0.04, type: "spring" }}
              className={letter === " " ? "w-1.5 sm:w-2 md:w-4" : "inline-block"}
            >
              {letter}
            </motion.span>
          ))}
        </h2>

        {/* Staggered Tagline */}
        <p className="text-green-light text-[10px] sm:text-xs md:text-base tracking-[0.05em] sm:tracking-[0.1em] md:tracking-[0.2em] font-semibold drop-shadow-[0_2px_8px_rgba(0,0,0,0.8)] flex flex-wrap justify-center gap-x-1.5 sm:gap-x-2 gap-y-1 sm:gap-y-1.5 max-w-[280px] sm:max-w-md text-center opacity-90">
          {tagline.map((word, index) => (
            <motion.span
              key={index}
              initial={{ opacity: 0, filter: "blur(8px)", y: 10 }}
              animate={{ opacity: 1, filter: "blur(0px)", y: 0 }}
              transition={{ duration: 0.6, delay: 1.2 + index * 0.1 }}
            >
              {word}
            </motion.span>
          ))}
        </p>

        {/* Fancy Loading Bar */}
        <motion.div
          initial={{ opacity: 0, scaleX: 0 }}
          animate={{ opacity: 1, scaleX: 1 }}
          transition={{ duration: 0.8, delay: 2.0, ease: "easeOut" }}
          className="mt-8 md:mt-12 w-48 sm:w-64 md:w-80 h-[3px] md:h-[4px] bg-white/10 rounded-full overflow-hidden backdrop-blur-md relative border border-white/5"
        >
          {/* Sweeping Highlight */}
          <motion.div
            className="absolute top-0 bottom-0 w-1/2 bg-gradient-to-r from-transparent via-white/40 to-transparent z-10"
            animate={{ x: ['-200%', '200%'] }}
            transition={{ duration: 1.5, repeat: Infinity, ease: "linear", delay: 2.0 }}
          />
          {/* Progress fill */}
          <motion.div
            className="h-full bg-gradient-to-r from-green-brand to-green-light rounded-full shadow-[0_0_15px_rgba(34,197,94,0.8)]"
            initial={{ width: '0%' }}
            animate={{ width: '100%' }}
            transition={{ duration: 2.5, ease: "easeInOut" }}
          />
        </motion.div>
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { useAuth } from '../context/AuthContext';

export default function Navbar({ onOpenLogin, onOpenSignup }) {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);
  const [profileOpen, setProfileOpen] = useState(false);
  const [moreOpen, setMoreOpen] = useState(false);
  const location = useLocation();
  const navigate = useNavigate();
  const { user, logout } = useAuth();

  useEffect(() => {
    const handleScroll = () => setScrolled(window.scrollY > 20);
    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  useEffect(() => {
    setMenuOpen(false);
  }, [location]);

  // Prevent body scroll when mobile menu is open
  useEffect(() => {
    if (menuOpen) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = '';
    }
    return () => { document.body.style.overflow = ''; };
  }, [menuOpen]);

  const isDashboard = location.pathname.startsWith('/student') || location.pathname.startsWith('/admin') || location.pathname.startsWith('/basic');
  if (isDashboard) return null;

  const navLinks = [
    { to: '/', label: 'Home' },
    { to: '/about', label: 'About' },
    { to: '/courses', label: 'Courses' },
    { to: '/gallery', label: 'Gallery' },
  ];

  const moreLinks = [
    { to: '/achievements', label: 'Achievements' },
    { to: '/counselling', label: 'Counselling' },
    { to: '/contact', label: 'Contact' },
  ];

  const handleLogout = () => {
    logout();
    navigate('/');
  };

  return (
    <>
      <motion.nav
        initial={{ y: -100 }}
        animate={{ y: 0 }}
        transition={{ type: 'spring', stiffness: 100, damping: 20 }}
        className={`fixed top-0 left-0 right-0 z-50 transition-all duration-300 ${
          scrolled
            ? 'bg-black/90 backdrop-blur-lg shadow-lg shadow-green-brand/5 border-b border-white/5'
            : 'bg-transparent'
        }`}
      >
        <div className="container-main">
          <div className="flex items-center justify-between h-[72px]">
            {/* Logo */}
            <Link to="/" className="flex items-center gap-3 no-underline group">
              <div className="relative">
                <div className="absolute -inset-1 bg-green-brand/20 rounded-xl blur opacity-0 group-hover:opacity-100 transition-opacity duration-500" />
                <img src="/Images/RBT Logo.jpeg" alt="RBT Mission Learning" width="40" height="40" decoding="async" className="relative w-10 h-10 rounded-xl object-cover shadow-lg" />
              </div>
              <div>
                <h1 className="text-base font-bold leading-tight tracking-tight font-[var(--font-heading)] text-white">
                  RBT MISSION
                </h1>
                <p className="text-[10px] font-medium tracking-widest uppercase text-green-brand">
                  LEARNING
                </p>
              </div>
            </Link>

            {/* Desktop Navigation */}
            <div className="hidden lg:flex items-center gap-1">
              {navLinks.map((link) => (
                <Link
                  key={link.to}
                  to={link.to}
                  className={`group px-4 py-2 text-sm font-medium transition-colors no-underline ${
                    location.pathname === link.to
                      ? 'text-white'
                      : 'text-white/70 hover:text-white'
                  }`}
                >
                  <span className="relative inline-block">
                    {link.label}
                    <span className={`absolute -bottom-1 left-0 w-full h-[2px] bg-green-brand origin-left transition-transform duration-300 ease-out ${
                      location.pathname === link.to ? 'scale-x-100' : 'scale-x-0 group-hover:scale-x-100'
                    }`} />
                  </span>
                </Link>
              ))}
              {/* More Dropdown */}
              <div className="relative">
                <button
                  onClick={() => setMoreOpen(!moreOpen)}
                  className={`group px-4 py-2 text-sm font-medium transition-colors flex items-center gap-1 cursor-pointer ${
                    moreOpen || moreLinks.some(l => location.pathname === l.to)
                      ? 'text-white'
                      : 'text-white/70 hover:text-white'
                  }`}
                >
                  <span className="relative inline-flex items-center gap-1">
                    More
                    <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" className={`transition-transform duration-300 ${moreOpen ? 'rotate-180' : ''}`}><path d="m6 9 6 6 6-6"/></svg>
                    <span className={`absolute -bottom-1 left-0 w-full h-[2px] bg-green-brand origin-left transition-transform duration-300 ease-out ${
                      moreOpen || moreLinks.some(l => location.pathname === l.to) ? 'scale-x-100' : 'scale-x-0 group-hover:scale-x-100'
                    }`} />
                  </span>
                </button>
                {moreOpen && (
                  <div className="absolute top-full right-0 mt-2 min-w-[12rem] bg-[#111111] border border-slate-800 rounded-xl shadow-2xl overflow-hidden py-1 whitespace-nowrap z-50">
                    {moreLinks.map((link) => (
                      <Link
                        key={link.to}
                        to={link.to}
                        onClick={() => setMoreOpen(false)}
                        className={`block px-4 py-2.5 text-sm font-medium no-underline transition-all ${
                          location.pathname === link.to
                            ? 'text-green-brand bg-green-brand/10'
                            : 'text-slate-300 hover:text-white hover:bg-white/5'
                        }`}
                      >
                        {link.label}
                      </Link>
                    ))}
                  </div>
                )}
              </div>
            </div>

            {/* Desktop Auth Buttons */}
            <div className="hidden lg:flex items-center gap-3">
              {user ? (
                <div className="relative">
                  <button 
                    onClick={() => setProfileOpen(!profileOpen)}
                    className="flex items-center gap-2 bg-white/5 hover:bg-white/10 border border-white/10 rounded-full py-1.5 px-2 pr-4 transition-all"
                  >
                    <div className="w-8 h-8 rounded-full bg-green-brand text-white flex items-center justify-center font-bold text-sm overflow-hidden border border-white/20">
                      {user.photoURL ? (
                        <img src={user.photoURL} alt={user.name} className="w-full h-full object-cover" />
                      ) : (
                        user.name ? user.name.charAt(0).toUpperCase() : 'S'
                      )}
                    </div>
                    <span className="text-white text-sm font-medium">
                      {user.name ? user.name.split(' ')[0] : 'Student'}
                    </span>
                    <svg className={`w-4 h-4 text-slate-400 transition-transform ${profileOpen ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7" />
                    </svg>
                  </button>

                  <AnimatePresence>
                    {profileOpen && (
                      <motion.div
                        initial={{ opacity: 0, y: 10, scale: 0.95 }}
                        animate={{ opacity: 1, y: 0, scale: 1 }}
                        exit={{ opacity: 0, y: 10, scale: 0.95 }}
                        transition={{ duration: 0.2 }}
                        className="absolute right-0 mt-2 w-48 bg-[#111] border border-white/10 rounded-xl shadow-2xl py-2 z-50 overflow-hidden"
                      >
                        <Link
                          to={user.role === 'admin' ? '/admin' : user.batch ? '/student' : '/basic'}
                          onClick={() => setProfileOpen(false)}
                          className="block px-4 py-2 text-sm text-white/80 hover:text-white hover:bg-white/5 transition-colors no-underline"
                        >
                          Dashboard
                        </Link>
                        <button 
                          onClick={() => { setProfileOpen(false); handleLogout(); }} 
                          className="w-full text-left px-4 py-2 text-sm text-red-400 hover:text-red-300 hover:bg-white/5 transition-colors"
                        >
                          Logout
                        </button>
                      </motion.div>
                    )}
                  </AnimatePresence>
                </div>
              ) : (
                <div className="flex items-center gap-2">
                  <button
                    onClick={onOpenLogin}
                    className="px-5 py-2 rounded-lg text-sm font-medium text-slate-300 hover:text-white hover:bg-white/5 transition-colors cursor-pointer border border-transparent"
                  >
                    Login
                  </button>
                  <button
                    onClick={onOpenSignup}
                    className="btn-primary !py-2 !px-5 !text-sm"
                  >
                    Sign Up
                  </button>
                </div>
              )}
            </div>

            {/* Mobile Menu Button */}
            <button
              onClick={() => setMenuOpen(!menuOpen)}
              className="lg:hidden flex flex-col items-center justify-center w-10 h-10 gap-1.5 relative z-[60]"
              aria-label="Toggle menu"
            >
              <motion.span
                animate={menuOpen ? { rotate: 45, y: 8 } : { rotate: 0, y: 0 }}
                className="block w-6 h-0.5 rounded-full bg-white origin-center"
              />
              <motion.span
                animate={menuOpen ? { opacity: 0, scale: 0 } : { opacity: 1, scale: 1 }}
                className="block w-6 h-0.5 rounded-full bg-white"
              />
              <motion.span
                animate={menuOpen ? { rotate: -45, y: -8 } : { rotate: 0, y: 0 }}
                className="block w-6 h-0.5 rounded-full bg-white origin-center"
              />
            </button>
          </div>
        </div>
      </motion.nav>

      {/* Mobile Menu */}
      <AnimatePresence>
        {menuOpen && (
          <>
            {/* Backdrop */}
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              className="fixed inset-0 z-40 bg-black/60 backdrop-blur-sm lg:hidden"
              onClick={() => setMenuOpen(false)}
            />
            {/* Menu Panel */}
            <motion.div
              initial={{ opacity: 0, x: '100%' }}
              animate={{ opacity: 1, x: 0 }}
              exit={{ opacity: 0, x: '100%' }}
              transition={{ type: 'spring', stiffness: 300, damping: 30 }}
              className="fixed top-0 right-0 bottom-0 w-[280px] z-50 bg-[#0a0a0a] border-l border-white/10 lg:hidden overflow-y-auto"
            >
              <div className="p-6">
                <div className="flex items-center justify-between mb-8">
                  <div className="flex items-center gap-2">
                    <img src="/Images/RBT Logo.jpeg" alt="RBT" width="32" height="32" decoding="async" className="w-8 h-8 rounded-lg object-cover" />
                    <span className="text-sm font-bold text-white">RBT MISSION</span>
                  </div>
                  <button
                    onClick={() => setMenuOpen(false)}
                    className="w-8 h-8 rounded-lg hover:bg-white/10 flex items-center justify-center text-slate-400 hover:text-white transition-colors"
                  >
                    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                      <path d="M18 6 6 18" /><path d="m6 6 12 12" />
                    </svg>
                  </button>
                </div>

                <nav className="flex flex-col gap-1">
                  {navLinks.map((link, i) => (
                    <motion.div
                      key={link.to}
                      initial={{ opacity: 0, x: 20 }}
                      animate={{ opacity: 1, x: 0 }}
                      transition={{ delay: i * 0.05 }}
                    >
                      <Link
                        to={link.to}
                        className={`flex items-center px-4 py-3 rounded-xl text-sm font-medium no-underline transition-all ${
                          location.pathname === link.to
                            ? 'bg-green-brand/10 text-green-brand border border-green-brand/20'
                            : 'text-white/70 hover:bg-white/5 hover:text-white'
                        }`}
                      >
                        {link.label}
                      </Link>
                    </motion.div>
                  ))}
                </nav>

                <div className="border-t border-white/10 my-6" />

                {user ? (
                  <div className="space-y-2 mt-4 p-4 bg-white/5 rounded-2xl border border-white/5">
                    <div className="flex items-center gap-3 mb-4">
                      <div className="w-10 h-10 rounded-full bg-green-brand text-white flex items-center justify-center font-bold text-lg overflow-hidden border border-white/20">
                        {user.photoURL ? (
                          <img src={user.photoURL} alt={user.name} className="w-full h-full object-cover" />
                        ) : (
                          user.name ? user.name.charAt(0).toUpperCase() : 'S'
                        )}
                      </div>
                      <div>
                        <p className="text-white font-medium">{user.name || 'Student'}</p>
                        <p className="text-xs text-slate-400 capitalize">{user.role || 'Student'}</p>
                      </div>
                    </div>
                    <Link 
                      to={user.role === 'admin' ? '/admin' : user.batch ? '/student' : '/basic'} 
                      onClick={() => setMenuOpen(false)}
                      className="flex items-center justify-center w-full py-2.5 bg-white/10 hover:bg-white/20 text-white rounded-xl text-sm font-medium transition-colors no-underline"
                    >
                      Go to Dashboard
                    </Link>
                    <button 
                      onClick={() => { setMenuOpen(false); handleLogout(); }} 
                      className="flex items-center justify-center w-full py-2.5 bg-red-500/10 hover:bg-red-500/20 text-red-400 rounded-xl text-sm font-medium transition-colors"
                    >
                      Logout
                    </button>
                  </div>
                ) : (
                  <div className="space-y-3 mt-4">
                    <button
                      onClick={() => {
                        setMenuOpen(false);
                        onOpenLogin();
                      }}
                      className="w-full py-2.5 rounded-xl bg-white/5 hover:bg-white/10 text-white text-sm font-medium transition-colors border border-white/10"
                    >
                      Login
                    </button>
                    <button
                      onClick={() => {
                        setMenuOpen(false);
                        onOpenSignup();
                      }}
                      className="btn-primary text-center w-full"
                    >
                      Sign Up
                    </button>
                  </div>
                )}
              </div>
            </motion.div>
          </>
        )}
      </AnimatePresence>
    </>
  );
}

