import { TableSkeleton } from '../../components/ui/Skeleton';
import { useState, useMemo } from 'react';
import { useRealtimeCollection } from '../../lib/useRealtimeCollection';
import { addDocument, updateDocument, deleteDocument, uploadFile } from '../../lib/firebaseHelpers';
import toast from 'react-hot-toast';
import Modal from '../../components/Modal';
import ExportButton from '../../components/ExportButton';

const CATEGORIES = [
  { id: 'jee-main', label: 'JEE Main' },
  { id: 'neet', label: 'NEET' },
  { id: 'class-8', label: 'Class 8' },
  { id: 'class-9', label: 'Class 9' },
  { id: 'class-10', label: 'Class 10' },
  { id: 'class-11', label: 'Class 11' },
  { id: 'class-12', label: 'Class 12' },
  { id: 'boards', label: 'Boards' },
];

const emptyForm = {
  title: '',
  description: '',
  category: 'jee-main',
  difficulty: 'Medium',
  duration: 30,
  marksPerQuestion: 4,
  negativeMarks: 1,
  questions: [],
};

const emptyQ = () => ({
  id: `q_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`,
  section: 'Physics',
  question: '',
  imageUrl: '',
  options: ['', '', '', ''],
  correctIndex: 0,
  marks: null, // null = use test default
  explanation: '',
});

function isQComplete(q) {
  return q.question.trim() && q.options.every(o => o.trim());
}

export default function ManageMockTests() {
  const { data: tests, loading } = useRealtimeCollection('mockTests', { fallback: [] });
  const [modal, setModal] = useState(false);
  const [editing, setEditing] = useState(null);
  const [form, setForm] = useState(emptyForm);
  const [filter, setFilter] = useState('all');
  const [activeQIdx, setActiveQIdx] = useState(0);
  const [jsonModal, setJsonModal] = useState(false);
  const [jsonText, setJsonText] = useState('');
  const [preview, setPreview] = useState(false);
  const [uploading, setUploading] = useState(false);

  const handleImageUpload = async (e, qIdx) => {
    const file = e.target.files?.[0];
    if (!file) return;
    if (!file.type.startsWith('image/')) {
      toast.error('Only images allowed');
      return;
    }
    if (file.size > 5 * 1024 * 1024) {
      toast.error('Image too large (max 5MB)');
      return;
    }
    setUploading(true);
    try {
      const path = `mockTestImages/${Date.now()}_${file.name.replace(/\s+/g, '_')}`;
      const url = await uploadFile(path, file);
      updateQ(qIdx, { imageUrl: url });
      toast.success('Image uploaded');
    } catch (err) {
      toast.error('Upload failed: ' + err.message);
    } finally {
      setUploading(false);
      e.target.value = '';
    }
  };

  const filtered = filter === 'all' ? tests : tests.filter(t => t.category === filter);
  const activeQ = form.questions[activeQIdx];

  const sections = useMemo(() => {
    const set = new Set(form.questions.map(q => q.section).filter(Boolean));
    return Array.from(set);
  }, [form.questions]);

  const openCreate = () => { setEditing(null); setForm(emptyForm); setActiveQIdx(0); setModal(true); };
  const openEdit = (t) => {
    setEditing(t);
    setForm({
      title: t.title || '',
      description: t.description || '',
      category: t.category || 'jee-main',
      difficulty: t.difficulty || 'Medium',
      duration: t.duration || 30,
      marksPerQuestion: t.marksPerQuestion ?? 4,
      negativeMarks: t.negativeMarks ?? 1,
      questions: (t.questions || []).map(q => ({
        section: 'Physics',
        imageUrl: '',
        marks: null,
        explanation: '',
        ...q,
      })),
    });
    setActiveQIdx(0);
    setModal(true);
  };

  const closeModal = () => { setModal(false); setEditing(null); setForm(emptyForm); setActiveQIdx(0); };

  const addQuestion = () => {
    setForm(f => ({ ...f, questions: [...f.questions, emptyQ()] }));
    setActiveQIdx(form.questions.length);
  };
  const removeQuestion = (idx) => {
    setForm(f => ({ ...f, questions: f.questions.filter((_, i) => i !== idx) }));
    setActiveQIdx(Math.max(0, idx - 1));
  };
  const dupQuestion = (idx) => {
    setForm(f => {
      const next = [...f.questions];
      next.splice(idx + 1, 0, { ...f.questions[idx], id: `q_${Date.now()}_${Math.random().toString(36).slice(2, 7)}` });
      return { ...f, questions: next };
    });
  };
  const moveQ = (idx, dir) => {
    const tgt = idx + dir;
    if (tgt < 0 || tgt >= form.questions.length) return;
    setForm(f => {
      const next = [...f.questions];
      [next[idx], next[tgt]] = [next[tgt], next[idx]];
      return { ...f, questions: next };
    });
    setActiveQIdx(cur => cur === idx ? tgt : cur === tgt ? idx : cur);
  };
  const updateQ = (idx, patch) => setForm(f => ({
    ...f,
    questions: f.questions.map((q, i) => i === idx ? { ...q, ...patch } : q),
  }));
  const updateOpt = (qIdx, oIdx, val) => setForm(f => ({
    ...f,
    questions: f.questions.map((q, i) => i === qIdx ? { ...q, options: q.options.map((o, j) => j === oIdx ? val : o) } : q),
  }));

  const bulkImport = () => {
    try {
      const parsed = JSON.parse(jsonText);
      if (!Array.isArray(parsed)) throw new Error('Must be array');
      const qs = parsed.map(p => ({
        ...emptyQ(),
        section: p.section || 'Physics',
        question: p.question || '',
        imageUrl: p.imageUrl || '',
        options: Array.isArray(p.options) && p.options.length === 4 ? p.options : ['', '', '', ''],
        correctIndex: typeof p.correctIndex === 'number' ? p.correctIndex : 0,
        explanation: p.explanation || '',
      }));
      setForm(f => ({ ...f, questions: [...f.questions, ...qs] }));
      toast.success(`Imported ${qs.length} questions`);
      setJsonModal(false);
      setJsonText('');
    } catch (err) {
      toast.error('Invalid JSON: ' + err.message);
    }
  };

  const save = async () => {
    if (!form.title.trim()) { toast.error('Title required'); return; }
    if (!form.questions.length) { toast.error('Add at least one question'); return; }
    for (const [i, q] of form.questions.entries()) {
      if (!q.question.trim()) { toast.error(`Q${i + 1}: question text missing`); return; }
      if (q.options.some(o => !o.trim())) { toast.error(`Q${i + 1}: all 4 options needed`); return; }
    }
    const payload = {
      ...form,
      duration: Number(form.duration) || 30,
      marksPerQuestion: Number(form.marksPerQuestion) || 4,
      negativeMarks: Number(form.negativeMarks) || 0,
      totalQuestions: form.questions.length,
      maxMarks: form.questions.reduce((s, q) => s + (Number(q.marks) || Number(form.marksPerQuestion) || 4), 0),
    };
    try {
      if (editing) {
        await updateDocument('mockTests', editing.id, payload);
        toast.success('Updated');
      } else {
        await addDocument('mockTests', payload);
        toast.success('Created');
      }
      closeModal();
    } catch (err) { toast.error(err.message); }
  };

  const remove = async (id) => {
    if (!confirm('Delete test?')) return;
    try {
      await deleteDocument('mockTests', id);
      toast.success('Deleted');
    } catch (err) { toast.error(err.message); }
  };

  return (
    <div className="p-6">
      <div className="flex justify-between items-center mb-6 flex-wrap gap-3">
        <div>
          <h1 className="text-2xl font-bold text-white">Mock Tests</h1>
          <p className="text-sm text-slate-400">NTA-style proctored MCQ tests</p>
        </div>
        <div className="flex gap-2">
          <ExportButton data={tests} filename="mock_tests" columns={[
            { key: 'title', label: 'Title' },
            { key: 'category', label: 'Category' },
            { key: 'difficulty', label: 'Difficulty' },
            { key: 'duration', label: 'Duration (min)' },
            { key: 'totalQuestions', label: 'Questions' },
            { key: 'maxMarks', label: 'Max Marks' },
            { key: 'marksPerQuestion', label: 'Marks per Q' },
            { key: 'negativeMarks', label: 'Negative Marks' },
            { key: 'description', label: 'Description' },
          ]} />
          <button onClick={openCreate} className="bg-green-brand hover:bg-green-600 text-white font-bold px-5 py-2.5 rounded-lg">
            + New Test
          </button>
        </div>
      </div>

      <div className="flex flex-wrap gap-2 mb-6">
        <button
          onClick={() => setFilter('all')}
          className={`px-3 py-1.5 rounded-full text-xs font-medium ${filter === 'all' ? 'bg-green-brand text-white' : 'bg-white/5 text-slate-400 border border-white/10'}`}
        >
          All ({tests.length})
        </button>
        {CATEGORIES.map(c => {
          const count = tests.filter(t => t.category === c.id).length;
          return (
            <button
              key={c.id}
              onClick={() => setFilter(c.id)}
              className={`px-3 py-1.5 rounded-full text-xs font-medium ${filter === c.id ? 'bg-green-brand text-white' : 'bg-white/5 text-slate-400 border border-white/10'}`}
            >
              {c.label} ({count})
            </button>
          );
        })}
      </div>

      {loading && <TableSkeleton />}

      {!loading && filtered.length === 0 && (
        <div className="bg-white/5 border border-white/10 rounded-2xl p-12 text-center">
          <p className="text-slate-400 mb-4">No mock tests yet.</p>
          <button onClick={openCreate} className="bg-green-brand hover:bg-green-600 text-white font-bold px-5 py-2.5 rounded-lg">
            Create First Test
          </button>
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {filtered.map(t => (
          <div key={t.id} className="bg-white/5 border border-white/10 rounded-2xl p-5">
            <div className="flex justify-between items-start mb-2">
              <span className="text-xs font-bold px-2 py-1 rounded bg-green-brand/10 text-green-brand">
                {CATEGORIES.find(c => c.id === t.category)?.label || t.category}
              </span>
              {t.difficulty && <span className="text-xs text-slate-400">{t.difficulty}</span>}
            </div>
            <h3 className="text-white font-bold mb-1 line-clamp-2">{t.title}</h3>
            <p className="text-xs text-slate-400 mb-3 line-clamp-2">{t.description}</p>
            <div className="grid grid-cols-3 gap-2 text-center text-xs mb-3">
              <div className="bg-black/30 rounded p-2">
                <div className="text-white font-bold">{t.questions?.length || 0}</div>
                <div className="text-slate-500 text-[10px]">Q's</div>
              </div>
              <div className="bg-black/30 rounded p-2">
                <div className="text-white font-bold">{t.duration || 30}</div>
                <div className="text-slate-500 text-[10px]">Mins</div>
              </div>
              <div className="bg-black/30 rounded p-2">
                <div className="text-white font-bold">{t.maxMarks ?? (t.questions?.length || 0) * (t.marksPerQuestion ?? 4)}</div>
                <div className="text-slate-500 text-[10px]">Marks</div>
              </div>
            </div>
            <div className="flex gap-2">
              <button onClick={() => openEdit(t)} className="flex-1 bg-white/10 hover:bg-white/20 text-white text-sm py-2 rounded">Edit</button>
              <button onClick={() => remove(t.id)} className="bg-red-500/20 hover:bg-red-500/30 text-red-400 text-sm py-2 px-3 rounded">Delete</button>
            </div>
          </div>
        ))}
      </div>

      <Modal isOpen={modal} onClose={closeModal} title={editing ? 'Edit Mock Test' : 'New Mock Test'} size="full">
        <div className="flex flex-col h-[80vh]">
          {/* Test meta strip */}
          <div className="grid grid-cols-2 md:grid-cols-6 gap-2 pb-3 border-b border-white/10">
            <input value={form.title} onChange={e => setForm({ ...form, title: e.target.value })}
              placeholder="Test title"
              className="md:col-span-2 bg-white/5 border border-white/10 rounded-lg px-3 py-2 text-white text-sm font-bold" />
            <select value={form.category} onChange={e => setForm({ ...form, category: e.target.value })}
              className="bg-white/5 border border-white/10 rounded-lg px-3 py-2 text-white text-sm">
              {CATEGORIES.map(c => <option key={c.id} value={c.id} className="bg-slate-900">{c.label}</option>)}
            </select>
            <input type="number" value={form.duration} onChange={e => setForm({ ...form, duration: e.target.value })}
              placeholder="Min" title="Duration (min)"
              className="bg-white/5 border border-white/10 rounded-lg px-3 py-2 text-white text-sm" />
            <input type="number" value={form.marksPerQuestion} onChange={e => setForm({ ...form, marksPerQuestion: e.target.value })}
              placeholder="Marks/Q" title="Marks per Q"
              className="bg-white/5 border border-white/10 rounded-lg px-3 py-2 text-white text-sm" />
            <input type="number" value={form.negativeMarks} onChange={e => setForm({ ...form, negativeMarks: e.target.value })}
              placeholder="-ve" title="Negative marks"
              className="bg-white/5 border border-white/10 rounded-lg px-3 py-2 text-white text-sm" />
          </div>

          {/* Split layout */}
          <div className="flex-1 flex overflow-hidden">
            {/* Left: Q list */}
            <div className="w-72 border-r border-white/10 flex flex-col overflow-hidden">
              <div className="p-3 border-b border-white/10 flex gap-2">
                <button onClick={addQuestion} className="flex-1 bg-green-brand hover:bg-green-600 text-white text-xs font-bold py-2 rounded">
                  + Add Q
                </button>
                <button onClick={() => setJsonModal(true)} title="Bulk import JSON"
                  className="bg-white/10 hover:bg-white/20 text-white text-xs px-3 rounded">
                  JSON
                </button>
              </div>
              <div className="flex-1 overflow-y-auto p-2 space-y-1">
                {form.questions.map((q, i) => {
                  const complete = isQComplete(q);
                  const active = i === activeQIdx;
                  const stop = (fn) => (e) => { e.stopPropagation(); e.preventDefault(); fn(); };
                  return (
                    <div key={q.id}
                      role="button"
                      onClick={() => setActiveQIdx(i)}
                      className={`p-2 rounded cursor-pointer border ${active ? 'bg-green-brand/20 border-green-brand' : 'bg-white/5 border-white/10 hover:bg-white/10'}`}>
                      <div className="flex items-center gap-2 min-w-0 mb-1.5">
                        <span className={`w-2 h-2 rounded-full flex-shrink-0 ${complete ? 'bg-green-500' : 'bg-amber-500'}`} />
                        <span className="text-xs text-white font-bold flex-shrink-0">Q{i + 1}</span>
                        <span className="text-[10px] text-slate-400 truncate flex-1">{q.question || '(empty)'}</span>
                      </div>
                      <div className="flex justify-between items-center">
                        <span className="text-[10px] text-slate-500 truncate">{q.section}</span>
                        <div className="flex gap-0.5 flex-shrink-0">
                          <button type="button" onClick={stop(() => moveQ(i, -1))} disabled={i === 0} title="Move up"
                            className="text-xs text-slate-300 hover:text-white hover:bg-white/10 disabled:opacity-20 disabled:hover:bg-transparent w-6 h-6 rounded flex items-center justify-center">↑</button>
                          <button type="button" onClick={stop(() => moveQ(i, 1))} disabled={i === form.questions.length - 1} title="Move down"
                            className="text-xs text-slate-300 hover:text-white hover:bg-white/10 disabled:opacity-20 disabled:hover:bg-transparent w-6 h-6 rounded flex items-center justify-center">↓</button>
                          <button type="button" onClick={stop(() => dupQuestion(i))} title="Duplicate"
                            className="text-xs text-slate-300 hover:text-white hover:bg-white/10 w-6 h-6 rounded flex items-center justify-center">⎘</button>
                          <button type="button" onClick={stop(() => { if (confirm(`Delete Q${i + 1}?`)) removeQuestion(i); })} title="Delete"
                            className="text-xs text-red-400 hover:text-red-300 hover:bg-red-500/10 w-6 h-6 rounded flex items-center justify-center">×</button>
                        </div>
                      </div>
                    </div>
                  );
                })}
                {form.questions.length === 0 && (
                  <p className="text-slate-500 text-xs text-center py-6">No questions yet</p>
                )}
              </div>
              <div className="p-2 border-t border-white/10 text-[10px] text-slate-400 grid grid-cols-2 gap-2">
                <div>Total: <span className="text-white font-bold">{form.questions.length}</span></div>
                <div>Done: <span className="text-green-400 font-bold">{form.questions.filter(isQComplete).length}</span></div>
              </div>
            </div>

            {/* Right: active Q editor */}
            <div className="flex-1 overflow-y-auto p-5">
              {!activeQ && (
                <div className="h-full flex flex-col items-center justify-center text-center">
                  <p className="text-slate-400 mb-3">No question selected</p>
                  <button onClick={addQuestion} className="bg-green-brand hover:bg-green-600 text-white px-5 py-2 rounded-lg text-sm font-bold">
                    + Add First Question
                  </button>
                </div>
              )}

              {activeQ && (
                <div className="max-w-3xl">
                  <div className="flex justify-between items-center mb-4">
                    <div className="flex items-center gap-3">
                      <span className="text-xl font-bold text-white">Question {activeQIdx + 1}</span>
                      <span className={`text-xs px-2 py-0.5 rounded ${isQComplete(activeQ) ? 'bg-green-500/20 text-green-400' : 'bg-amber-500/20 text-amber-400'}`}>
                        {isQComplete(activeQ) ? '✓ Complete' : '⚠ Incomplete'}
                      </span>
                    </div>
                    <button onClick={() => setPreview(p => !p)} className="text-xs bg-white/10 hover:bg-white/20 text-white px-3 py-1.5 rounded">
                      {preview ? 'Edit' : '👁 Preview'}
                    </button>
                  </div>

                  {preview ? (
                    <div className="bg-white text-black rounded-lg p-6 space-y-4">
                      <div className="flex justify-between text-xs text-gray-600">
                        <span>{activeQ.section} · Q{activeQIdx + 1}</span>
                        <span>Marks: +{activeQ.marks || form.marksPerQuestion}  / −{form.negativeMarks}</span>
                      </div>
                      <p className="text-base font-medium whitespace-pre-wrap">{activeQ.question || '(empty)'}</p>
                      {activeQ.imageUrl && <img src={activeQ.imageUrl} alt="" className="max-h-60 rounded" />}
                      <div className="space-y-2">
                        {activeQ.options.map((o, oi) => (
                          <div key={oi} className={`flex gap-3 p-3 rounded border ${activeQ.correctIndex === oi ? 'bg-green-50 border-green-400' : 'border-gray-200'}`}>
                            <span className="font-bold">{String.fromCharCode(65 + oi)}.</span>
                            <span>{o || '(empty)'}</span>
                          </div>
                        ))}
                      </div>
                      {activeQ.explanation && (
                        <div className="bg-blue-50 border-l-4 border-blue-400 p-3 text-sm">
                          <strong>Explanation:</strong> {activeQ.explanation}
                        </div>
                      )}
                    </div>
                  ) : (
                    <div className="space-y-4">
                      <div className="grid grid-cols-2 gap-3">
                        <div>
                          <label className="text-xs text-slate-400 block mb-1">Section</label>
                          <input value={activeQ.section} onChange={e => updateQ(activeQIdx, { section: e.target.value })}
                            list="sections-list"
                            placeholder="Physics / Chemistry / Math"
                            className="w-full bg-white/5 border border-white/10 rounded-lg px-3 py-2 text-white text-sm" />
                          <datalist id="sections-list">
                            {sections.map(s => <option key={s} value={s} />)}
                            <option value="Physics" />
                            <option value="Chemistry" />
                            <option value="Mathematics" />
                            <option value="Biology" />
                          </datalist>
                        </div>
                        <div>
                          <label className="text-xs text-slate-400 block mb-1">Marks override (blank = test default)</label>
                          <input type="number" value={activeQ.marks ?? ''} onChange={e => updateQ(activeQIdx, { marks: e.target.value === '' ? null : Number(e.target.value) })}
                            placeholder={String(form.marksPerQuestion)}
                            className="w-full bg-white/5 border border-white/10 rounded-lg px-3 py-2 text-white text-sm" />
                        </div>
                      </div>

                      <div>
                        <label className="text-xs text-slate-400 block mb-1">Question text *</label>
                        <textarea value={activeQ.question} onChange={e => updateQ(activeQIdx, { question: e.target.value })}
                          rows={4} placeholder="Type the question here..."
                          className="w-full bg-white/5 border border-white/10 rounded-lg px-3 py-2.5 text-white text-sm" />
                      </div>

                      <div>
                        <label className="text-xs text-slate-400 block mb-1">Image (optional) — upload or paste URL</label>
                        <div className="flex gap-2">
                          <input value={activeQ.imageUrl} onChange={e => updateQ(activeQIdx, { imageUrl: e.target.value })}
                            placeholder="https://... or upload below"
                            className="flex-1 bg-white/5 border border-white/10 rounded-lg px-3 py-2 text-white text-sm" />
                          <label className={`cursor-pointer bg-white/10 hover:bg-white/20 text-white text-sm px-4 py-2 rounded-lg flex items-center gap-2 ${uploading ? 'opacity-50 pointer-events-none' : ''}`}>
                            {uploading ? '⏳ Uploading...' : '📁 Upload'}
                            <input type="file" accept="image/*" hidden
                              onChange={(e) => handleImageUpload(e, activeQIdx)} />
                          </label>
                          {activeQ.imageUrl && (
                            <button onClick={() => updateQ(activeQIdx, { imageUrl: '' })}
                              className="bg-red-500/20 hover:bg-red-500/30 text-red-400 text-sm px-3 py-2 rounded-lg">
                              ×
                            </button>
                          )}
                        </div>
                        {activeQ.imageUrl && (
                          <img src={activeQ.imageUrl} alt="" className="mt-2 max-h-48 rounded border border-white/10"
                            onError={(e) => { e.target.style.display = 'none'; }} />
                        )}
                        <p className="text-[10px] text-slate-500 mt-1">JPG/PNG, max 5MB. Stored in Firebase Storage.</p>
                      </div>

                      <div>
                        <label className="text-xs text-slate-400 block mb-2">Options * (click radio to mark correct)</label>
                        <div className="space-y-2">
                          {activeQ.options.map((opt, oi) => (
                            <div key={oi} className={`flex gap-3 items-center p-3 rounded-lg border ${activeQ.correctIndex === oi ? 'bg-green-brand/10 border-green-brand' : 'bg-white/5 border-white/10'}`}>
                              <label className="flex items-center gap-2 cursor-pointer">
                                <input type="radio" name={`correct_active`} checked={activeQ.correctIndex === oi}
                                  onChange={() => updateQ(activeQIdx, { correctIndex: oi })} className="accent-green-brand w-4 h-4" />
                                <span className="text-sm text-white font-bold w-5">{String.fromCharCode(65 + oi)}.</span>
                              </label>
                              <input value={opt} onChange={e => updateOpt(activeQIdx, oi, e.target.value)}
                                placeholder={`Option ${String.fromCharCode(65 + oi)}`}
                                className="flex-1 bg-transparent border-0 focus:outline-none text-white text-sm" />
                              {activeQ.correctIndex === oi && <span className="text-xs text-green-brand font-bold">✓ Correct</span>}
                            </div>
                          ))}
                        </div>
                      </div>

                      <div>
                        <label className="text-xs text-slate-400 block mb-1">Explanation (optional, shown after submission)</label>
                        <textarea value={activeQ.explanation} onChange={e => updateQ(activeQIdx, { explanation: e.target.value })}
                          rows={2} placeholder="Why is this answer correct..."
                          className="w-full bg-white/5 border border-white/10 rounded-lg px-3 py-2 text-white text-sm" />
                      </div>

                      <div className="flex gap-2 pt-2">
                        <button onClick={() => dupQuestion(activeQIdx)} className="bg-white/10 hover:bg-white/20 text-white text-xs px-3 py-2 rounded">
                          ⎘ Duplicate
                        </button>
                        <button onClick={() => { if (confirm(`Delete Q${activeQIdx + 1}?`)) removeQuestion(activeQIdx); }} className="bg-red-500/20 hover:bg-red-500/30 text-red-400 text-xs px-3 py-2 rounded">
                          × Delete this Q
                        </button>
                      </div>
                    </div>
                  )}
                </div>
              )}
            </div>
          </div>

          {/* Footer */}
          <div className="flex gap-3 pt-3 border-t border-white/10">
            <button onClick={closeModal} className="flex-1 bg-white/5 hover:bg-white/10 text-white py-2.5 rounded-lg">Cancel</button>
            <button onClick={save} className="flex-1 bg-green-brand hover:bg-green-600 text-white font-bold py-2.5 rounded-lg">
              {editing ? 'Save Changes' : 'Create Test'}
            </button>
          </div>
        </div>
      </Modal>

      {/* JSON bulk import */}
      <Modal isOpen={jsonModal} onClose={() => setJsonModal(false)} title="Bulk Import Questions (JSON)" size="lg">
        <div className="space-y-3">
          <p className="text-xs text-slate-400">
            Paste JSON array. Each item: <code className="bg-black/30 px-1 rounded">{`{question, options:[a,b,c,d], correctIndex, section?, explanation?, imageUrl?}`}</code>
          </p>
          <textarea value={jsonText} onChange={e => setJsonText(e.target.value)}
            rows={14} placeholder={`[\n  {"question":"2+2?","options":["3","4","5","6"],"correctIndex":1,"section":"Math"}\n]`}
            className="w-full bg-black/40 border border-white/10 rounded-lg px-3 py-2 text-white text-xs font-mono" />
          <div className="flex gap-2">
            <button onClick={() => setJsonModal(false)} className="flex-1 bg-white/5 hover:bg-white/10 text-white py-2 rounded-lg">Cancel</button>
            <button onClick={bulkImport} className="flex-1 bg-green-brand hover:bg-green-600 text-white font-bold py-2 rounded-lg">Import</button>
          </div>
        </div>
      </Modal>
    </div>
  );
}

import { TableSkeleton } from '../../components/ui/Skeleton';
import toast from 'react-hot-toast'
import { updateDocument, deleteDocument } from '../../lib/firebaseHelpers'
import { useRealtimeCollection } from '../../lib/useRealtimeCollection'
import { formatCurrency } from '../../lib/invoice'
import { useState } from 'react'
import Modal from '../../components/Modal'
import InvoiceView from '../../components/InvoiceView'
import ExportButton from '../../components/ExportButton'
import { doc, setDoc } from 'firebase/firestore'
import { db } from '../../lib/firebase'

export default function ManagePayments() {
  const { data: payments, loading } = useRealtimeCollection('payments')
  const { data: settings } = useRealtimeCollection('settings')
  const [selectedInvoice, setSelectedInvoice] = useState(null)

  const [isEditRevenueModalOpen, setIsEditRevenueModalOpen] = useState(false)
  const [revenueInput, setRevenueInput] = useState('')

  const overrideRevenue = settings?.find(s => s.id === 'revenue')?.overrideAmount

  const verifyPayment = async (id) => {
    try {
      await updateDocument('payments', id, { status: 'verified', verifiedAt: new Date().toISOString() })
      toast.success('Payment verified')
    } catch (err) { toast.error(err.message || 'Verify failed') }
  }

  const rejectPayment = async (id) => {
    try {
      await updateDocument('payments', id, { status: 'rejected', rejectedAt: new Date().toISOString() })
      toast.success('Payment rejected')
    } catch (err) { toast.error(err.message || 'Reject failed') }
  }

  const deleteInvoice = async (id) => {
    if (window.confirm("Are you sure you want to delete this invoice? This action cannot be undone.")) {
      try {
        await deleteDocument('payments', id)
        toast.success('Invoice deleted')
      } catch (err) { toast.error(err.message || 'Delete failed') }
    }
  }

  const openEditRevenueModal = () => {
    setRevenueInput(overrideRevenue !== undefined && overrideRevenue !== null ? overrideRevenue.toString() : '');
    setIsEditRevenueModalOpen(true);
  }

  const saveRevenue = async () => {
    try {
      if (revenueInput.trim() === '') {
        await setDoc(doc(db, 'settings', 'revenue'), { overrideAmount: null }, { merge: true })
        toast.success('Revenue calculation set to automatic')
      } else {
        const num = parseFloat(revenueInput);
        if (isNaN(num)) throw new Error("Invalid amount");
        await setDoc(doc(db, 'settings', 'revenue'), { overrideAmount: num }, { merge: true })
        toast.success('Total revenue updated')
      }
      setIsEditRevenueModalOpen(false)
    } catch (err) {
      toast.error(err.message || 'Update failed')
    }
  }

  const calculatedRevenue = payments
    .filter((p) => p.status === 'verified' || p.status === 'paid' || p.status === 'success')
    .reduce((sum, p) => sum + (p.amount || 0), 0)

  const totalRevenue = overrideRevenue !== undefined && overrideRevenue !== null ? overrideRevenue : calculatedRevenue;

  const pendingCount = payments.filter((p) => p.status === 'pending').length

  const statusColors = {
    pending: 'badge-gold',
    verified: 'badge-green',
    rejected: 'badge-red',
    paid: 'badge-green',
    success: 'badge-green',
  }

  return (
    <div>
      <div className="flex items-center justify-between mb-6">
        <div>
          <h1 className="text-2xl font-bold text-white">Manage Payments</h1>
          <p className="text-sm text-slate-400">{payments.length} transactions</p>
        </div>
        <ExportButton data={payments} filename="payments" columns={[
          { key: 'invoiceNumber', label: 'Invoice #' },
          { key: 'paymentId', label: 'Payment ID' },
          { key: 'studentName', label: 'Student' },
          { key: 'studentEmail', label: 'Email' },
          { key: 'videoTitle', label: 'Video' },
          { key: 'courseTitle', label: 'Course' },
          { key: 'amount', label: 'Amount (₹)' },
          { key: 'gpayTransactionId', label: 'UPI Txn ID' },
          { key: 'status', label: 'Status' },
          { key: 'verifiedAt', label: 'Verified At' },
          { key: 'rejectedAt', label: 'Rejected At' },
        ]} />
      </div>

      {/* Stats */}
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 mb-6">
        <div className="bg-[#111111] rounded-2xl p-4 border border-slate-800">
          <div className="flex justify-between items-start mb-1">
            <p className="text-xs text-slate-400">Total Revenue</p>
            <button 
              onClick={openEditRevenueModal}
              className="text-xs text-slate-500 hover:text-white transition-colors"
              title="Edit Revenue"
            >
              <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M12 20h9"></path><path d="M16.5 3.5a2.12 2.12 0 0 1 3 3L7 19l-4 1 1-4Z"></path></svg>
            </button>
          </div>
          <p className="text-xl font-bold text-green-brand">{formatCurrency(totalRevenue)}</p>
          {overrideRevenue !== undefined && overrideRevenue !== null && (
            <p className="text-[10px] text-slate-500 mt-1">Manual Override Active</p>
          )}
        </div>
        <div className="bg-[#111111] rounded-2xl p-4 border border-slate-800">
          <p className="text-xs text-slate-400 mb-1">Pending Verification</p>
          <p className="text-xl font-bold text-amber-500">{pendingCount}</p>
        </div>
        <div className="bg-[#111111] rounded-2xl p-4 border border-slate-800">
          <p className="text-xs text-slate-400 mb-1">Total Transactions</p>
          <p className="text-xl font-bold text-white">{payments.length}</p>
        </div>
      </div>

      {loading ? (
        <div className="py-8"><TableSkeleton /></div>
      ) : (
        <div className="bg-[#111111] rounded-2xl border border-slate-800 overflow-hidden">
          <div className="table-container">
            <table>
              <thead>
                <tr>
                  <th className="text-white">Invoice</th>
                  <th className="text-white">Student</th>
                  <th className="text-white">Video / Course</th>
                  <th className="text-white">Amount</th>
                  <th className="text-white">Transaction ID</th>
                  <th className="text-white">Status</th>
                  <th className="text-white">Actions</th>
                </tr>
              </thead>
              <tbody>
                {payments.map((p) => (
                  <tr key={p.id}>
                    <td className="font-mono text-xs text-white">{p.invoiceNumber || p.paymentId || p.id}</td>
                    <td className="text-white text-sm">{p.studentName}</td>
                    <td className="text-slate-300 text-sm">{p.videoTitle || p.courseTitle || 'Course Purchase'}</td>
                    <td className="text-green-brand font-semibold">{formatCurrency(p.amount)}</td>
                    <td className="font-mono text-xs text-slate-400">{p.gpayTransactionId || p.paymentId || p.id}</td>
                    <td><span className={`badge ${statusColors[p.status] || 'bg-slate-500/20 text-slate-400'}`}>{p.status}</span></td>
                    <td>
                      <div className="flex gap-3 items-center">
                        <button 
                          onClick={() => setSelectedInvoice(p)} 
                          className="text-xs text-blue-400 font-bold cursor-pointer hover:text-blue-300 transition-colors"
                        >
                          Download
                        </button>
                        <button 
                          onClick={() => deleteInvoice(p.id)} 
                          className="text-xs text-red-500 font-bold cursor-pointer hover:text-red-400 transition-colors"
                        >
                          Delete
                        </button>
                        {p.status === 'pending' && (
                          <>
                            <button onClick={() => verifyPayment(p.id)} className="text-xs text-green-brand font-bold cursor-pointer hover:text-green-400 transition-colors">Verify</button>
                            <button onClick={() => rejectPayment(p.id)} className="text-xs text-red-500 font-bold cursor-pointer hover:text-red-400 transition-colors">Reject</button>
                          </>
                        )}
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* Invoice Modal */}
      <Modal isOpen={!!selectedInvoice} onClose={() => setSelectedInvoice(null)} title="Invoice Details">
        {selectedInvoice && (
          <InvoiceView 
            invoice={{
              invoiceNumber: selectedInvoice.invoiceNumber || selectedInvoice.paymentId || selectedInvoice.id,
              date: selectedInvoice.paidAt?.toDate ? new Date(selectedInvoice.paidAt.toDate()).toLocaleString() : new Date(selectedInvoice.createdAt?.toDate?.() || Date.now()).toLocaleString(),
              studentName: selectedInvoice.studentName || 'Student',
              studentEmail: selectedInvoice.studentEmail || '',
              videoTitle: selectedInvoice.videoTitle || selectedInvoice.courseTitle || 'Course Enrollment',
              amount: selectedInvoice.amount,
              transactionId: selectedInvoice.gpayTransactionId || selectedInvoice.paymentId || selectedInvoice.id,
              paymentMethod: selectedInvoice.type === 'razorpay_webhook' || selectedInvoice.type === 'razorpay' || selectedInvoice.paymentId ? 'Razorpay' : 'UPI / Google Pay',
              upiId: (selectedInvoice.type === 'razorpay_webhook' || selectedInvoice.type === 'razorpay' || selectedInvoice.paymentId) ? null : (import.meta.env.VITE_UPI_ID || 'rbtmission@upi'),
              status: selectedInvoice.status
            }}
            onClose={() => setSelectedInvoice(null)} 
          />
        )}
      </Modal>

      {/* Edit Revenue Modal */}
      <Modal isOpen={isEditRevenueModalOpen} onClose={() => setIsEditRevenueModalOpen(false)} title="Edit Total Revenue">
        <div className="space-y-4">
          <p className="text-sm text-slate-300">
            Enter new total revenue override amount. Leave blank to automatically calculate from invoices.
          </p>
          <div>
            <label className="block text-sm font-medium text-slate-400 mb-1">Override Amount (₹)</label>
            <input
              type="number"
              value={revenueInput}
              onChange={(e) => setRevenueInput(e.target.value)}
              placeholder="e.g. 50000"
              className="w-full bg-[#0a0a0a] border border-slate-800 rounded-xl px-4 py-3 text-white focus:outline-none focus:border-green-brand/50 transition-colors"
            />
          </div>
          <div className="flex gap-3 pt-2">
            <button
              onClick={() => setIsEditRevenueModalOpen(false)}
              className="flex-1 px-4 py-3 bg-slate-800 hover:bg-slate-700 text-white rounded-xl font-medium transition-colors"
            >
              Cancel
            </button>
            <button
              onClick={saveRevenue}
              className="flex-1 px-4 py-3 bg-green-brand hover:bg-green-500 text-[#0a0a0a] rounded-xl font-bold transition-colors"
            >
              Save
            </button>
          </div>
        </div>
      </Modal>
    </div>
  )
}

import { TableSkeleton } from '../../components/ui/Skeleton';
import { useState } from 'react';
import toast from 'react-hot-toast';
import Modal from '../../components/Modal';
import { addDocument, updateDocument, deleteDocument } from '../../lib/firebaseHelpers';
import { useRealtimeCollection } from '../../lib/contentApi';
import { httpsCallable } from 'firebase/functions';
import { functions } from '../../lib/firebase';
import { collection, query, where, getDocs } from 'firebase/firestore';
import { db } from '../../lib/firebase';
import InvoiceView from '../../components/InvoiceView';
import { formatCurrency } from '../../lib/invoice';
import ExportButton from '../../components/ExportButton';

const emptyForm = { studentId: '', name: '', email: '', phone: '', course: '', class: 'Class 10', password: '' };

export default function ManageStudents() {
  const { data: students, loading } = useRealtimeCollection('students', 'createdAt');
  const { data: courses } = useRealtimeCollection('courses', 'createdAt');
  const { data: allEnrollments } = useRealtimeCollection('enrollments', 'enrolledAt');
  const [modal, setModal] = useState(false);
  const [busy, setBusy] = useState(false);
  const [editing, setEditing] = useState(null);
  const [form, setForm] = useState(emptyForm);

  const [coursesModal, setCoursesModal] = useState(false);
  const [selectedStudent, setSelectedStudent] = useState(null);
  const [enrollments, setEnrollments] = useState([]);
  const [purchases, setPurchases] = useState([]);
  const [fetchingEnrollments, setFetchingEnrollments] = useState(false);
  const [selectedInvoice, setSelectedInvoice] = useState(null);

  const closeModal = () => { setModal(false); setEditing(null); setForm(emptyForm); };

  const openCourses = async (s) => {
    setSelectedStudent(s);
    setCoursesModal(true);
    setFetchingEnrollments(true);
    try {
      const q = query(collection(db, 'enrollments'), where('uid', '==', s.id));
      const snap = await getDocs(q);
      const data = snap.docs.map(d => ({ id: d.id, ...d.data() }));
      setEnrollments(data);

      const payQ1 = getDocs(query(collection(db, 'payments'), where('studentId', '==', s.id)));
      const payQ2 = getDocs(query(collection(db, 'payments'), where('studentId', '==', s.studentId)));
      const invQ = getDocs(query(collection(db, 'invoices'), where('studentUid', '==', s.id)));

      const [p1, p2, inv] = await Promise.all([payQ1, payQ2, invQ]);
      const combined = [];
      const seen = new Set();
      
      [...p1.docs, ...p2.docs].forEach(d => {
        if (!seen.has(d.id)) {
          seen.add(d.id);
          combined.push({ id: d.id, _type: 'payment', ...d.data() });
        }
      });
      inv.docs.forEach(d => {
        combined.push({ id: d.id, _type: 'invoice', ...d.data() });
      });
      
      // Sort by latest first based on ID or whatever, or just leave as is
      setPurchases(combined);

    } catch (err) {
      toast.error('Failed to fetch data');
    } finally {
      setFetchingEnrollments(false);
    }
  };

  const toggleCourseStatus = async (enrollmentId, currentStatus) => {
    const newStatus = currentStatus === 'revoked' ? 'active' : 'revoked';
    try {
      await updateDocument('enrollments', enrollmentId, { status: newStatus });
      setEnrollments(prev => prev.map(e => e.id === enrollmentId ? { ...e, status: newStatus } : e));
      toast.success(`Course ${newStatus === 'revoked' ? 'revoked' : 'reactivated'}`);
    } catch (err) {
      toast.error('Failed to update status');
    }
  };

  const openEdit = (s) => {
    setEditing(s);
    setForm({
      studentId: s.studentId || '',
      name: s.name || '',
      email: s.email || '',
      phone: s.phone || '',
      course: s.course || '',
      class: s.class || 'Class 10',
      password: '',
    });
    setModal(true);
  };

  const save = async () => {
    if (!form.studentId || !form.name) { toast.error('Student ID and Name required'); return; }
    setBusy(true);
    try {
      if (editing) {
        // Edit: update Cloud Function to update Auth and Firestore
        const updateFn = httpsCallable(functions, 'updateStudent');
        const result = await updateFn({
          uid: editing.id,
          studentId: form.studentId.toUpperCase(),
          name: form.name.trim(),
          email: form.email || '',
          phone: form.phone || '',
          course: form.course || '',
          password: form.password || undefined,
        });
        if (result.data.ok || result.data.success) {
          toast.success('Student updated securely');
        }
      } else {
        // Create: use Cloud Function (creates Firebase Auth account)
        if (!form.password || form.password.length < 8) {
          toast.error('Password required (min 8 characters)');
          setBusy(false);
          return;
        }
        const createFn = httpsCallable(functions, 'createStudent');
        const result = await createFn({
          studentId: form.studentId,
          name: form.name,
          email: form.email || '',
          phone: form.phone || '',
          course: form.course || '',
          password: form.password,
        });
        if (result.data.ok || result.data.success) {
          toast.success('Student account created — can login now');
        }
      }
      closeModal();
    } catch (err) {
      toast.error(err.message || 'Failed to save');
    } finally { setBusy(false); }
  };

  const disable = async (s) => {
    if (!confirm(`Disable ${s.name}? They can't login after this.`)) return;
    try {
      const fn = httpsCallable(functions, 'disableStudent');
      await fn({ uid: s.id });
      toast.success('Student disabled');
    } catch (err) { toast.error(err.message); }
  };

  const enable = async (s) => {
    try {
      const fn = httpsCallable(functions, 'disableStudent');
      await fn({ uid: s.id, disabled: false });
      toast.success('Student enabled');
    } catch (err) { toast.error(err.message); }
  };

  const remove = async (s) => {
    if (!confirm(`Delete ${s.name} permanently? This deletes their account and data.`)) return;
    try {
      const fn = httpsCallable(functions, 'deleteStudent');
      await fn({ uid: s.id });
      toast.success('Student deleted');
    } catch (err) { toast.error(err.message); }
  };

  const getStudentCourses = (s) => {
    // Get active enrollments for this student
    const activeEnrollments = allEnrollments.filter(e => e.uid === s.id && e.status !== 'revoked');
    
    let courseNames = [];
    if (activeEnrollments.length > 0) {
      courseNames = activeEnrollments.map(e => {
        const c = courses.find(course => course.id === e.courseId);
        return c ? c.title : 'Unknown Course';
      });
    }

    // Include manually typed course if any
    if (s.course && !courseNames.includes(s.course)) {
      courseNames.unshift(s.course);
    }

    if (courseNames.length === 0) return 'No courses';
    return courseNames.join(', ');
  };

  return (
    <div>
      <div className="flex items-center justify-between mb-6">
        <div>
          <h1 className="text-2xl font-bold text-white">Manage Students</h1>
          <p className="text-sm text-slate-400">{students.length} students enrolled</p>
        </div>
        <div className="flex gap-2">
          <ExportButton
            data={students}
            filename="students"
            columns={[
              { key: 'studentId', label: 'Student ID' },
              { key: 'name', label: 'Name' },
              { key: 'email', label: 'Email' },
              { key: 'phone', label: 'Phone' },
              { key: 'class', label: 'Class' },
              { key: 'course', label: 'Course' },
              { key: 'batch', label: 'Batch' },
              { key: 'status', label: 'Status' },
              { key: 'createdAt', label: 'Created At' },
            ]}
          />
          <button onClick={() => setModal(true)} className="btn-primary shadow-lg">+ Add Student</button>
        </div>
      </div>

      <div className="bg-[#111111] rounded-2xl border border-slate-800 shadow-sm overflow-hidden">
        <div className="table-container">
          {loading ? (
            <div className="py-8"><TableSkeleton /></div>
          ) : students.length === 0 ? (
            <div className="p-12 text-center text-slate-500">No students yet. Click + Add Student to begin.</div>
          ) : (
            <table className="w-full">
              <thead className="bg-white/5 border-b border-slate-800">
                <tr>
                  <th className="text-white font-bold">Student ID</th>
                  <th className="text-white font-bold">Name</th>
                  <th className="text-white font-bold">Email</th>
                  <th className="text-white font-bold">Course</th>
                  <th className="text-white font-bold">Status</th>
                  <th className="text-white font-bold">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-800">
                {students.map(s => (
                  <tr key={s.id} className="hover:bg-white/5 transition-colors">
                    <td className="font-mono text-[11px] text-slate-500 font-bold">{s.studentId}</td>
                    <td className="font-semibold text-white">{s.name}</td>
                    <td className="text-slate-700 text-sm">{s.email || '-'}</td>
                    <td className="text-slate-700 font-medium">{getStudentCourses(s)}</td>
                    <td>
                      <span className={`badge ${s.status === 'disabled' ? 'badge-red' : 'badge-green'}`}>
                        {s.status === 'disabled' ? 'Disabled' : 'Active'}
                      </span>
                    </td>
                    <td>
                      <div className="flex gap-3">
                        <button onClick={() => openCourses(s)} className="text-sm font-bold text-purple-400 hover:text-purple-300 cursor-pointer">Courses</button>
                        <button onClick={() => openEdit(s)} className="text-sm font-bold text-blue-400 hover:text-blue-300 cursor-pointer">Edit</button>
                        {s.status === 'disabled' ? (
                          <button onClick={() => enable(s)} className="text-sm font-bold text-green-brand cursor-pointer">Enable</button>
                        ) : (
                          <button onClick={() => disable(s)} className="text-sm font-bold text-amber-400 cursor-pointer">Disable</button>
                        )}
                        <button onClick={() => remove(s)} className="text-sm font-bold text-red-400 cursor-pointer">Delete</button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      </div>

      <Modal isOpen={modal} onClose={closeModal} title={editing ? 'Edit Student' : 'Add Student'}>
        <div className="space-y-4 p-1">
          <div>
            <label className="text-sm font-bold text-white mb-1.5 block">Student ID *</label>
            <input className="w-full bg-white/5 border border-slate-700 rounded-xl px-4 py-2.5 text-white focus:border-green-brand focus:ring-0 transition-all outline-none" value={form.studentId} onChange={e => setForm({ ...form, studentId: e.target.value })} placeholder="e.g. STU001" />
          </div>
          <div>
            <label className="text-sm font-bold text-white mb-1.5 block">Full Name *</label>
            <input className="w-full bg-white/5 border border-slate-700 rounded-xl px-4 py-2.5 text-white focus:border-green-brand focus:ring-0 transition-all outline-none" value={form.name} onChange={e => setForm({ ...form, name: e.target.value })} placeholder="John Doe" />
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div>
              <label className="text-sm font-bold text-white mb-1.5 block">Email</label>
              <input type="email" className="w-full bg-white/5 border border-slate-700 rounded-xl px-4 py-2.5 text-white focus:border-green-brand focus:ring-0 transition-all outline-none" value={form.email} onChange={e => setForm({ ...form, email: e.target.value })} placeholder="student@example.com" />
            </div>
            <div>
              <label className="text-sm font-bold text-white mb-1.5 block">Phone</label>
              <input className="w-full bg-white/5 border border-slate-700 rounded-xl px-4 py-2.5 text-white focus:border-green-brand focus:ring-0 transition-all outline-none" value={form.phone} onChange={e => setForm({ ...form, phone: e.target.value })} placeholder="+91..." />
            </div>
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div>
              <label className="text-sm font-bold text-white mb-1.5 block">Class</label>
              <select className="w-full bg-white/5 border border-slate-700 rounded-xl px-4 py-2.5 text-white focus:border-green-brand focus:ring-0 transition-all outline-none" value={form.class} onChange={e => setForm({ ...form, class: e.target.value })}>
                {['Class 8', 'Class 9', 'Class 10', 'Class 11', 'Class 12'].map(c => <option key={c}>{c}</option>)}
              </select>
            </div>
            <div>
              <label className="text-sm font-bold text-white mb-1.5 block">Course</label>
              <input className="w-full bg-white/5 border border-slate-700 rounded-xl px-4 py-2.5 text-white focus:border-green-brand focus:ring-0 transition-all outline-none" value={form.course} onChange={e => setForm({ ...form, course: e.target.value })} placeholder="Physics Pro" />
            </div>
          </div>
          <div>
            <label className="text-sm font-bold text-white mb-1.5 block">Password {editing ? '(Leave blank to keep current)' : '*'}</label>
            <input type="password" className="w-full bg-white/5 border border-slate-700 rounded-xl px-4 py-2.5 text-white focus:border-green-brand focus:ring-0 transition-all outline-none" value={form.password} onChange={e => setForm({ ...form, password: e.target.value })} placeholder="Min 8 characters" />
            <p className="text-xs text-slate-500 mt-1">{editing ? 'Only fill this if you want to explicitly reset their password.' : 'Student will login with this password'}</p>
          </div>
          <button onClick={save} disabled={busy} className="btn-primary w-full shadow-lg mt-2 disabled:opacity-60">
            {busy ? 'Saving...' : editing ? 'Update Student' : 'Create Student Account'}
          </button>
        </div>
      </Modal>

      <Modal isOpen={coursesModal} onClose={() => setCoursesModal(false)} title={`Courses for ${selectedStudent?.name}`}>
        <div className="p-1">
          {fetchingEnrollments ? (
            <div className="text-slate-400 text-center py-4">Loading data...</div>
          ) : (
            <div className="space-y-6">
              <div>
                <h3 className="text-white font-bold mb-3">Enrolled Courses</h3>
                {enrollments.length === 0 ? (
                  <div className="text-slate-500 text-center py-4 bg-white/5 rounded-xl border border-slate-800">No enrolled courses.</div>
                ) : (
                  <div className="space-y-3">
                    {enrollments.map(e => {
                      const course = courses.find(c => c.id === e.courseId);
                      const isRevoked = e.status === 'revoked';
                      return (
                        <div key={e.id} className="bg-white/5 border border-slate-700 rounded-xl p-4 flex items-center justify-between">
                          <div>
                            <p className="font-bold text-white mb-0.5">{course?.title || 'Unknown Course'}</p>
                            <p className="text-xs text-slate-400">Purchased: {e.enrolledAt?.toDate ? new Date(e.enrolledAt.toDate()).toLocaleString() : 'Unknown'}</p>
                            {isRevoked && <span className="inline-block mt-1 text-[10px] uppercase font-bold tracking-wider text-red-400 bg-red-400/10 px-2 py-0.5 rounded">Revoked</span>}
                          </div>
                          <button 
                            onClick={() => toggleCourseStatus(e.id, e.status)}
                            className={`text-sm font-bold cursor-pointer ${isRevoked ? 'text-green-brand hover:text-green-400' : 'text-amber-400 hover:text-amber-300'}`}
                          >
                            {isRevoked ? 'Reactivate' : 'Revoke Access'}
                          </button>
                        </div>
                      );
                    })}
                  </div>
                )}
              </div>

              <div>
                <h3 className="text-white font-bold mb-3">Invoices & Payments</h3>
                {purchases.length === 0 ? (
                  <div className="text-slate-500 text-center py-4 bg-white/5 rounded-xl border border-slate-800">No purchases found.</div>
                ) : (
                  <div className="space-y-3">
                    {purchases.map(p => (
                      <div key={p.id} className="bg-white/5 border border-slate-700 rounded-xl p-4 flex flex-col sm:flex-row sm:items-center justify-between gap-3">
                        <div>
                          <p className="font-bold text-white mb-0.5">{p.invoiceNumber || p.paymentId || 'INV-MANUAL'}</p>
                          <p className="text-xs text-slate-400">{p._type === 'invoice' ? p.courseName : (p.courseTitle || p.videoTitle)}</p>
                          <div className="flex items-center gap-2 mt-1">
                            <span className="text-green-brand font-semibold text-sm">{formatCurrency(p.amount)}</span>
                            <span className="text-[10px] uppercase font-bold tracking-wider text-slate-300 bg-slate-800 px-2 py-0.5 rounded">{p.status}</span>
                          </div>
                        </div>
                        <button 
                          onClick={() => setSelectedInvoice(p)}
                          className="text-sm font-bold text-blue-400 hover:text-blue-300 cursor-pointer text-left sm:text-right"
                        >
                          View Invoice
                        </button>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            </div>
          )}
        </div>
      </Modal>

      {/* Invoice Modal overlaid */}
      <Modal isOpen={!!selectedInvoice} onClose={() => setSelectedInvoice(null)} title="Invoice Details">
        {selectedInvoice && (
          <InvoiceView 
            invoice={
              selectedInvoice._type === 'payment' ? {
                invoiceNumber: selectedInvoice.invoiceNumber || selectedInvoice.paymentId || selectedInvoice.id,
                date: selectedInvoice.paidAt?.toDate ? new Date(selectedInvoice.paidAt.toDate()).toLocaleString() : new Date(selectedInvoice.createdAt?.toDate?.() || Date.now()).toLocaleString(),
                studentName: selectedInvoice.studentName || selectedStudent?.name,
                studentEmail: selectedInvoice.studentEmail || selectedStudent?.email,
                videoTitle: selectedInvoice.videoTitle || selectedInvoice.courseTitle,
                amount: selectedInvoice.amount,
                transactionId: selectedInvoice.gpayTransactionId || selectedInvoice.paymentId || selectedInvoice.id,
                paymentMethod: selectedInvoice.type === 'razorpay_webhook' || selectedInvoice.type === 'razorpay' ? 'Razorpay' : 'UPI / Google Pay',
                upiId: (selectedInvoice.type === 'razorpay_webhook' || selectedInvoice.type === 'razorpay') ? null : (import.meta.env.VITE_UPI_ID || 'rbtmission@upi'),
                status: selectedInvoice.status
              } : {
                invoiceNumber: selectedInvoice.invoiceNumber,
                date: selectedInvoice.dueDate || 'N/A',
                studentName: selectedInvoice.studentName || selectedStudent?.name,
                studentEmail: selectedInvoice.studentEmail || selectedStudent?.email,
                courseName: selectedInvoice.courseName,
                description: selectedInvoice.description,
                amount: selectedInvoice.amount,
                transactionId: selectedInvoice.id,
                paymentMethod: 'Manual Invoice',
                upiId: null,
                status: selectedInvoice.status
              }
            } 
            onClose={() => setSelectedInvoice(null)} 
          />
        )}
      </Modal>
    </div>
  );
}

